// Edite este mapa antes de probar: el chat_id se obtiene escribiéndole /start al bot y
// mirando el log del nodo Telegram Trigger, o con @userinfobot.
const TELEFONO_A_CHAT_ID = {
  '3009998877': 123456789, // Marta Gil (ejemplo del Instructivo 5) -> reemplazar
};
const datos = items[0].json.body ?? items[0].json;
const chat_id = TELEFONO_A_CHAT_ID[datos.cliente.telefono];
if (!chat_id) throw new Error(`Sin chat_id para el teléfono ${datos.cliente.telefono}: agréguelo al mapa del nodo de Código.`);
return [{ json: { ...datos, chat_id } }];

// Recupera el último cotizacion_ref que le mandamos a este chat_id (memoria del workflow).
const datos = $getWorkflowStaticData('global');
const chat_id = items[0].json.message.chat.id;
const texto = String(items[0].json.message.text ?? '').trim().toLowerCase();
const cotizacion_ref = datos[`cot_${chat_id}`];
if (!cotizacion_ref) throw new Error(`No hay una cotización pendiente registrada para el chat ${chat_id}.`);
const aceptada = ['si', 'sí', 'yes', 'acepto'].includes(texto);
return [{ json: { cotizacion_ref, aceptada, texto_original: texto } }];

// Guarda qué cotización le mandamos a cada chat_id, para interpretar la respuesta después.
const datos = $getWorkflowStaticData('global');
datos[`cot_${items[0].json.chat_id}`] = items[0].json.cotizacion_ref;
return items;
